(function () {
var nav = document.getElementById('navbar');
if (!nav) return;
var hamburger = document.getElementById('hamburger');
var links = document.getElementById('navLinks');
var subItems = nav.querySelectorAll('.has-sub');
function closeSubs(except) {
subItems.forEach(function (li) {
if (li === except) return;
li.classList.remove('open');
var t = li.querySelector('.sub-toggle');
if (t) t.setAttribute('aria-expanded', 'false');
});
}
function openMenu() {
links.classList.add('open');
hamburger.classList.add('open');
hamburger.setAttribute('aria-expanded', 'true');
document.body.classList.add('mobile-menu-open');
}
function closeMenu() {
links.classList.remove('open');
hamburger.classList.remove('open');
hamburger.setAttribute('aria-expanded', 'false');
document.body.classList.remove('mobile-menu-open');
closeSubs();
}
if (hamburger && links) {
hamburger.addEventListener('click', function () {
links.classList.contains('open') ? closeMenu() : openMenu();
});
links.querySelectorAll('a').forEach(function (a) { a.addEventListener('click', closeMenu); });
window.addEventListener('resize', function () { if (window.innerWidth > 1024) closeMenu(); });
}
nav.querySelectorAll('.sub-toggle').forEach(function (toggle) {
toggle.addEventListener('click', function (e) {
e.stopPropagation();
var li = toggle.closest('.has-sub');
var willOpen = !li.classList.contains('open');
closeSubs(li);
li.classList.toggle('open', willOpen);
toggle.setAttribute('aria-expanded', willOpen ? 'true' : 'false');
});
});
document.addEventListener('click', function (e) { if (!e.target.closest('.has-sub')) closeSubs(); });
document.addEventListener('keydown', function (e) {
if (e.key === 'Escape') { closeSubs(); if (links && links.classList.contains('open')) closeMenu(); }
});
function onScroll() { nav.classList.toggle('scrolled', window.scrollY > 50); }
onScroll();
window.addEventListener('scroll', onScroll, { passive: true });
document.addEventListener('click', function (e) {
var a = e.target.closest('a');
if (!a || typeof window.gtag !== 'function') return;
var href = a.getAttribute('href') || '';
var name = null;
if (href.indexOf('tel:') === 0) name = 'click_telefon';
else if (href.indexOf('wa.me') !== -1) name = 'click_whatsapp';
else if (href.indexOf('programeaza-te') !== -1) name = 'click_programare';
if (!name) return;
var zone = a.closest('[data-loc]');
window.gtag('event', name, { link_location: zone ? zone.getAttribute('data-loc') : 'continut', page_path: location.pathname });
});
})();
